	@Test
	void iriCapturePreservesSuppliedNamespaceAndLocalNameSplit() {
		String lexicalIri = "urn:split:rest:resource";
		IRI simpleIri = SIMPLE.createIRI("urn:split:", "rest:resource");
		IRI genericIri = GENERIC.createIRI("urn:split:", "rest:resource");
		IRI alternateSimpleIri = SIMPLE.createIRI("urn:", "split:rest:resource");
		IRI alternateGenericIri = GENERIC.createIRI("urn:", "split:rest:resource");

		assertEquals(lexicalIri, simpleIri.stringValue());
		assertEquals(simpleIri.stringValue(), genericIri.stringValue());
		assertEquals(simpleIri.stringValue(), alternateSimpleIri.stringValue());
		assertEquals(simpleIri.stringValue(), alternateGenericIri.stringValue());
		assertEquals(simpleIri, genericIri);
		assertEquals(simpleIri, alternateSimpleIri);
		assertEquals(simpleIri, alternateGenericIri);

		LmdbQueryValueIdentity simpleIdentity = new LmdbQueryValueIdentity.Capture().of(simpleIri);
		LmdbQueryValueIdentity genericIdentity = new LmdbQueryValueIdentity.Capture().of(genericIri);
		LmdbQueryValueIdentity alternateSimpleIdentity = new LmdbQueryValueIdentity.Capture().of(alternateSimpleIri);
		LmdbQueryValueIdentity alternateGenericIdentity = new LmdbQueryValueIdentity.Capture().of(alternateGenericIri);

		assertNotNull(simpleIdentity);
		assertNotNull(genericIdentity);
		assertNotNull(alternateSimpleIdentity);
		assertNotNull(alternateGenericIdentity);
		assertAll(
				() -> assertEquals(simpleIdentity, genericIdentity,
						"equal supplied splits produce equal cache identities"),
				() -> assertNotEquals(simpleIdentity, alternateSimpleIdentity,
						"different public namespace/local-name views need distinct cache identities"),
				() -> assertNotEquals(genericIdentity, alternateGenericIdentity,
						"AbstractValueFactory's public split must remain distinguishable too"),
				() -> assertIriSplit(simpleIri, (IRI) simpleIdentity.value()),
				() -> assertIriSplit(genericIri, (IRI) genericIdentity.value()),
				() -> assertIriSplit(alternateSimpleIri, (IRI) alternateSimpleIdentity.value()),
				() -> assertIriSplit(alternateGenericIri, (IRI) alternateGenericIdentity.value()));
	}

	@Test
	void numericAndPlainLexicalFormsOfOneRdfTermRetainDifferentConversions() {
		Literal numeric = SIMPLE.createLiteral(1000);
		Literal plainLexical = SIMPLE.createLiteral("1000", CoreDatatype.XSD.INT.getIri());
		assertInstanceOf(NumericLiteral.class, numeric);
		assertEquals(numeric, plainLexical, "both inputs represent the same RDF literal");
		assertEquals(numeric.getLabel(), plainLexical.getLabel());
		assertEquals(numeric.getDatatype(), plainLexical.getDatatype());
		assertEquals(-24, numeric.byteValue());
		assertThrows(NumberFormatException.class, plainLexical::byteValue,
				"the lexical literal parses an xsd:byte instead of narrowing the stored int");

		LmdbQueryValueIdentity numericIdentity = new LmdbQueryValueIdentity.Capture().of(numeric);
		LmdbQueryValueIdentity lexicalIdentity = new LmdbQueryValueIdentity.Capture().of(plainLexical);
		assertNotNull(numericIdentity);
		assertNotNull(lexicalIdentity);
		Literal detachedNumeric = (Literal) numericIdentity.value();
		Literal detachedLexical = (Literal) lexicalIdentity.value();
		assertAll(
				() -> assertNotEquals(numericIdentity, lexicalIdentity,
						"cache identity must retain the observable numeric backing representation"),
				() -> assertEquals(-24, detachedNumeric.byteValue(),
						"detached numeric backing keeps narrowing behavior"),
				() -> assertThrows(NumberFormatException.class, detachedLexical::byteValue,
						"detached plain lexical literal keeps parse behavior"));
	}

	@Test
	void packedPlanningDeclinesValuesWhoseObservableRepresentationExceedsRdfIdentity() {
		Literal numeric = SIMPLE.createLiteral(1000);
		Literal lexical = SIMPLE.createLiteral("1000", CoreDatatype.XSD.INT.getIri());
		IRI noncanonicalIri = SIMPLE.createIRI("urn:split:", "rest:resource");
		IRI canonicalIri = SIMPLE.createIRI(noncanonicalIri.stringValue());
		assertEquals(numeric, lexical);
		assertEquals(noncanonicalIri, canonicalIri);
		assertNotEquals(noncanonicalIri.getNamespace(), canonicalIri.getNamespace());

		TupleExpr plain = constantSource(lexical);
		TupleExpr numericSource = constantSource(numeric);
		TupleExpr canonical = constantSource(canonicalIri);
		TupleExpr noncanonical = constantSource(noncanonicalIri);
		TupleExpr mixed = constantSource(numeric, lexical, canonicalIri, noncanonicalIri);
		var optimizer = new LmdbCascadesOptimizer(new EvaluationStatistics(), false);
		assertNotNull(optimizer.optimizeWithResult(constantSource(lexical), null, EmptyBindingSet.getInstance())
				.cascadesPlan(), "the ordinary lexical control must actually reach packed planning");
		assertAll(
				() -> assertNotNull(PackedPlanCache.structuralKey(plain, LmdbCacheValueCopies.CODEC)),
				() -> assertNotNull(PackedPlanCache.structuralKey(canonical, LmdbCacheValueCopies.CODEC)),
				() -> assertNull(PackedPlanCache.structuralKey(numericSource, LmdbCacheValueCopies.CODEC),
						"an RDF-only packed cache key cannot distinguish numeric and lexical conversions"),
				() -> assertNull(PackedPlanCache.structuralKey(noncanonical, LmdbCacheValueCopies.CODEC),
						"an RDF-only packed cache key cannot distinguish IRI namespace splits"),
				() -> assertNull(PackedPlanCache.structuralKey(mixed, LmdbCacheValueCopies.CODEC),
						"one source may contain two equal RDF terms with different observable values"),
				() -> assertNull(
						optimizer.optimizeWithResult(mixed, null, EmptyBindingSet.getInstance()).cascadesPlan(),
						"ordinary packed planning must decline the same source before interning its values"),
				() -> assertTrue(String.valueOf(mixed.getStringMetricPlanned("optimizer.cascadesFallbackReason"))
						.contains("root.packedValueRepresentation"), "fallback must name the representation boundary"));
	}

