	@Test
	void decimalCopiesRetainNegativeScaleAndTrailingZeros() {
		BigDecimal negativeScale = new BigDecimal("1E+3");
		Literal compact = SIMPLE.createLiteral(negativeScale);
		Literal sameLexicalSimple = SIMPLE.createLiteral("1000", CoreDatatype.XSD.DECIMAL.getIri());
		assertEquals("1000", compact.getLabel());
		assertEquals(compact, sameLexicalSimple, "negative-scale and scale-zero values share the same RDF term");
		assertEquals(-3, compact.decimalValue().scale());
		assertEquals(0, sameLexicalSimple.decimalValue().scale());

		LmdbQueryValueIdentity compactIdentity = new LmdbQueryValueIdentity.Capture().of(compact);
		LmdbQueryValueIdentity plainIdentity = new LmdbQueryValueIdentity.Capture().of(sameLexicalSimple);
		assertNotNull(compactIdentity);
		assertNotNull(plainIdentity);
		Literal compactCopy = (Literal) compactIdentity.value();
		Literal lexicalCopy = (Literal) plainIdentity.value();
		Literal trailingZeros = SIMPLE.createLiteral(new BigDecimal("12.3400"));
		LmdbQueryValueIdentity trailingIdentity = new LmdbQueryValueIdentity.Capture().of(trailingZeros);
		assertNotNull(trailingIdentity);
		Literal trailingCopy = (Literal) trailingIdentity.value();
		assertAll(
				() -> assertNotEquals(compactIdentity, plainIdentity,
						"cache identity must preserve the observable BigDecimal scale"),
				() -> assertEquals(negativeScale, compactCopy.decimalValue(), "negative scale survives detachment"),
				() -> assertEquals(sameLexicalSimple.decimalValue(), lexicalCopy.decimalValue(),
						"plain lexical scale remains unchanged"),
				() -> assertEquals(new BigDecimal("12.3400"), trailingCopy.decimalValue(),
						"trailing decimal zeros survive detachment"));
	}

	@Test
	void floatingPointCopiesRetainSignedZeroAndDistinctNaNPayloads() {
		float negativeFloatZero = Float.intBitsToFloat(0x80000000);
		Literal floatZero = SIMPLE.createLiteral(negativeFloatZero);
		LmdbQueryValueIdentity floatZeroIdentity = new LmdbQueryValueIdentity.Capture().of(floatZero);
		assertNotNull(floatZeroIdentity);
		Literal floatZeroCopy = (Literal) floatZeroIdentity.value();

		double negativeDoubleZero = Double.longBitsToDouble(0x8000000000000000L);
		Literal doubleZero = SIMPLE.createLiteral(negativeDoubleZero);
		LmdbQueryValueIdentity doubleZeroIdentity = new LmdbQueryValueIdentity.Capture().of(doubleZero);
		assertNotNull(doubleZeroIdentity);
		Literal doubleZeroCopy = (Literal) doubleZeroIdentity.value();

		float floatNaNValueOne = Float.intBitsToFloat(0x7fc00001);
		float floatNaNValueTwo = Float.intBitsToFloat(0x7fc00002);
		Literal floatNaNOne = SIMPLE.createLiteral(floatNaNValueOne);
		Literal floatNaNTwo = SIMPLE.createLiteral(floatNaNValueTwo);
		LmdbQueryValueIdentity floatNaNIdentityOne = new LmdbQueryValueIdentity.Capture().of(floatNaNOne);
		LmdbQueryValueIdentity floatNaNIdentityTwo = new LmdbQueryValueIdentity.Capture().of(floatNaNTwo);

		double doubleNaNValueOne = Double.longBitsToDouble(0x7ff8000000000001L);
		double doubleNaNValueTwo = Double.longBitsToDouble(0x7ff8000000000002L);
		Literal doubleNaNOne = SIMPLE.createLiteral(doubleNaNValueOne);
		Literal doubleNaNTwo = SIMPLE.createLiteral(doubleNaNValueTwo);
		LmdbQueryValueIdentity doubleNaNIdentityOne = new LmdbQueryValueIdentity.Capture().of(doubleNaNOne);
		LmdbQueryValueIdentity doubleNaNIdentityTwo = new LmdbQueryValueIdentity.Capture().of(doubleNaNTwo);

		assertAll(
				() -> assertEquals(Float.floatToRawIntBits(negativeFloatZero),
						Float.floatToRawIntBits(floatZeroCopy.floatValue()), "negative float zero"),
				() -> assertEquals(Double.doubleToRawLongBits(negativeDoubleZero),
						Double.doubleToRawLongBits(doubleZeroCopy.doubleValue()), "negative double zero"),
				() -> assertNotEquals(floatNaNIdentityOne, floatNaNIdentityTwo,
						"different raw float NaN payloads remain distinguishable"),
				() -> assertEquals(Float.floatToRawIntBits(floatNaNValueOne),
						Float.floatToRawIntBits(((Literal) floatNaNIdentityOne.value()).floatValue()),
						"first float NaN payload"),
				() -> assertEquals(Float.floatToRawIntBits(floatNaNValueTwo),
						Float.floatToRawIntBits(((Literal) floatNaNIdentityTwo.value()).floatValue()),
						"second float NaN payload"),
				() -> assertNotEquals(doubleNaNIdentityOne, doubleNaNIdentityTwo,
						"different raw double NaN payloads remain distinguishable"),
				() -> assertEquals(Double.doubleToRawLongBits(doubleNaNValueOne),
						Double.doubleToRawLongBits(((Literal) doubleNaNIdentityOne.value()).doubleValue()),
						"first double NaN payload"),
				() -> assertEquals(Double.doubleToRawLongBits(doubleNaNValueTwo),
						Double.doubleToRawLongBits(((Literal) doubleNaNIdentityTwo.value()).doubleValue()),
						"second double NaN payload"));
	}

