	@Test
	void repeatedCaptureMaterializationPreservesNumericScaleAndTripleAliases() {
		Literal negativeScale = SIMPLE.createLiteral(new BigDecimal("1E+3"));
		LmdbQueryValueIdentity.Capture numericCapture = new LmdbQueryValueIdentity.Capture();
		LmdbQueryValueIdentity numericIdentity = numericCapture.of(negativeScale);
		assertNotNull(numericIdentity);
		assertSame(numericIdentity, numericCapture.of(negativeScale), "capture memoizes repeated source values");
		Literal firstNumericCopy = (Literal) numericIdentity.value();
		Literal secondNumericCopy = (Literal) new LmdbQueryValueIdentity.Capture().of(firstNumericCopy).value();
		assertAll(
				() -> assertEquals(-3, firstNumericCopy.decimalValue().scale(), "first materialization retains scale"),
				() -> assertEquals(-3, secondNumericCopy.decimalValue().scale(), "repeated round trip retains scale"));

		IRI shared = SIMPLE.createIRI("urn:cache-alias:value");
		TripleTerm triple = SIMPLE.createTripleTerm(shared, shared, shared);
		LmdbQueryValueIdentity.Capture graphCapture = new LmdbQueryValueIdentity.Capture();
		LmdbQueryValueIdentity graphIdentity = graphCapture.of(triple);
		assertNotNull(graphIdentity);
		assertSame(graphIdentity, graphCapture.of(triple), "capture cache reuses an identical graph identity");
		assertSame(graphCapture.of(shared), graphCapture.of(shared), "one graph child has one cached identity");
		TripleTerm firstTripleCopy = (TripleTerm) graphIdentity.value();
		TripleTerm secondTripleCopy = (TripleTerm) graphIdentity.value();
		assertAll(
				() -> assertSame(firstTripleCopy.getSubject(), firstTripleCopy.getPredicate(),
						"first materialization preserves shared subject/predicate"),
				() -> assertSame(firstTripleCopy.getSubject(), firstTripleCopy.getObject(),
						"first materialization preserves shared subject/object"),
				() -> assertSame(secondTripleCopy.getSubject(), secondTripleCopy.getPredicate(),
						"repeated materialization preserves shared subject/predicate"),
				() -> assertSame(secondTripleCopy.getSubject(), secondTripleCopy.getObject(),
						"repeated materialization preserves shared subject/object"));
	}

