	@ParameterizedTest(name = "includeInferred={0}")
	@ValueSource(booleans = { false, true })
	void parsedOrdinaryLiteralQueryHitsPipelineCacheWithNativeAdjacency(boolean includeInferred,
			@TempDir Path directory) throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,ospc,posc")
				.setNativeEvaluationEnabled(true)
				.setSketchEstimatorEnabled(false)
				.setFrontierEstimatorMode(FrontierEstimatorMode.OFF)
				.setDirectAdjacencyEnabled(true)
				.setDirectAdjacencyMode(DirectAdjacencyMode.PREFER)
				.setDirectAdjacencyCoverage(DirectAdjacencyCoverage.FULL);
		config.setExperimentalQueryOptimizations(true);
		LmdbStore store = new LmdbStore(directory.resolve("store").toFile(), config);
		SailRepository repository = new SailRepository(store);
		repository.init();
		try {
			seed(repository);
			LmdbTestUtil.awaitPostReadyInitialization(store, 30, java.util.concurrent.TimeUnit.SECONDS);
			assertTrue(store.getBackingStore().directAdjacencyStore().rebuildNowForTest());
			assertTrue(store.awaitDirectAdjacencyReady(30, java.util.concurrent.TimeUnit.SECONDS),
					store.getDirectAdjacencyReadinessDescription());
			List<Map<String, Long>> bags = new ArrayList<>();
			List<String> cacheHits = new ArrayList<>();
			for (int iteration = 1; iteration <= 2; iteration++) {
				try (var connection = repository.getConnection()) {
					TupleQuery query = connection.prepareTupleQuery(QUERY);
					query.setIncludeInferred(includeInferred);
					TupleExpr plan = (TupleExpr) query.explain(Explanation.Level.Optimized).tupleExpr();
					String pipelineHit = plannedMetric(plan, "optimizer.pipelinePlanCacheHit");
					cacheHits.add(pipelineHit);
					bags.add(readBag(query));
					System.err.println(
							"BUILTIN_VALUE_CACHE includeInferred=" + includeInferred + " iteration=" + iteration
									+ " pipelineHit=" + pipelineHit + " bag=" + bags.getLast());
				}
			}
			assertEquals(bags.get(0), bags.get(1), "fresh equivalent parsed queries must return equal result bags");
			Map<String, Long> expected = new TreeMap<>();
			expected.put("urn:builtin-cache:s1\u0000selected", 1L);
			expected.put("urn:builtin-cache:s2\u0000selected", 1L);
			if (includeInferred) {
				expected.put("urn:builtin-cache:s3\u0000selected", 1L);
			}
			assertEquals(expected, bags.get(0), "explicit and inferred source results must match their selected plane");
			assertFalse("true".equals(cacheHits.get(0)), "first execution should not be a warm cache hit");
			assertEquals("true", cacheHits.get(1), "the second fresh parsed query must hit the pipeline cache");
		} finally {
			repository.shutDown();
		}
	}

	private static Stream<Arguments> immutableBuiltinValues() {
		IRI datatype = SIMPLE.createIRI("urn:builtin-cache:datatype");
		TripleTerm genericNested = GENERIC.createTripleTerm(GENERIC.createBNode("generic-subject"),
				GENERIC.createIRI("urn:builtin-cache:outer"),
				GENERIC.createTripleTerm(GENERIC.createIRI("urn:builtin-cache:inner-subject"),
						GENERIC.createIRI("urn:builtin-cache:inner"),
						GENERIC.createLiteral("nested", "ar", Literal.BaseDirection.RTL)));
		TripleTerm simpleNested = SIMPLE.createTripleTerm(SIMPLE.createIRI("urn:builtin-cache:simple-subject"),
				SIMPLE.createIRI("urn:builtin-cache:simple-outer"),
				SIMPLE.createTripleTerm(SIMPLE.createBNode("simple-inner-subject"),
						SIMPLE.createIRI("urn:builtin-cache:simple-inner"),
						SIMPLE.createLiteral("nested", "he", Literal.BaseDirection.LTR)));
		return Stream.of(
				Arguments.of("generic IRI", (Value) GENERIC.createIRI("urn:builtin-cache:generic-iri")),
				Arguments.of("generic blank node", (Value) GENERIC.createBNode("generic-bnode")),
				Arguments.of("generic typed string", (Value) GENERIC.createLiteral("generic string")),
				Arguments.of("generic explicit typed literal",
						(Value) GENERIC.createLiteral("42", CoreDatatype.XSD.INTEGER.getIri())),
				Arguments.of("generic int overload", (Value) GENERIC.createLiteral(42)),
				Arguments.of("generic BigInteger overload",
						(Value) GENERIC.createLiteral(new BigInteger("1234567890123"))),
				Arguments.of("generic decimal overload", (Value) GENERIC.createLiteral(new BigDecimal("1234.500"))),
				Arguments.of("generic double overload", (Value) GENERIC.createLiteral(1.25d)),
				Arguments.of("generic boolean overload", (Value) GENERIC.createLiteral(true)),
				Arguments.of("generic language literal", (Value) GENERIC.createLiteral("bonjour", "fr")),
				Arguments.of("generic directional literal",
						(Value) GENERIC.createLiteral("שלום", "he", Literal.BaseDirection.RTL)),
				Arguments.of("generic nested triple term", (Value) genericNested),
				Arguments.of("simple IRI", (Value) SIMPLE.createIRI("urn:builtin-cache:simple-iri")),
				Arguments.of("simple blank node", (Value) SIMPLE.createBNode("simple-bnode")),
				Arguments.of("simple string literal", (Value) SIMPLE.createLiteral("simple string")),
				Arguments.of("simple typed literal", (Value) SIMPLE.createLiteral("simple typed", datatype)),
				Arguments.of("simple integer overload", (Value) SIMPLE.createLiteral(23)),
				Arguments.of("simple BigInteger overload",
						(Value) SIMPLE.createLiteral(new BigInteger("9876543210123"))),
				Arguments.of("simple decimal overload", (Value) SIMPLE.createLiteral(new BigDecimal("9876.250"))),
				Arguments.of("simple double overload", (Value) SIMPLE.createLiteral(2.5d)),
				Arguments.of("simple boolean overload", (Value) SIMPLE.createLiteral(false)),
				Arguments.of("simple language literal", (Value) SIMPLE.createLiteral("salut", "fr")),
				Arguments.of("simple directional literal",
						(Value) SIMPLE.createLiteral("שלום", "he", Literal.BaseDirection.RTL)),
				Arguments.of("simple nested triple term", (Value) simpleNested));
	}

	private static Stream<Arguments> callerOwnedNumericWrappers() {
		ObservedBigInteger integer = new ObservedBigInteger("1234567890123");
		Literal integerLiteral = SIMPLE.createLiteral(integer);
		integer.observe = true;
		ObservedBigDecimal decimal = new ObservedBigDecimal("1234.500");
		Literal decimalLiteral = SIMPLE.createLiteral(decimal);
		decimal.observe = true;
		return Stream.of(
				Arguments.of("caller BigInteger",
						new NumericWrapperCase(integerLiteral, integer.overriddenConversions)),
				Arguments.of("caller BigDecimal",
						new NumericWrapperCase(decimalLiteral, decimal.overriddenConversions)));
	}

	private static void assertEquivalentRdfValue(Value expected, Value actual, String path) {
		if (expected instanceof IRI expectedIri) {
			IRI actualIri = assertInstanceOf(IRI.class, actual, path + " remains an IRI");
			assertEquals(expectedIri.stringValue(), actualIri.stringValue(), path + " IRI lexical value");
			return;
		}
		if (expected instanceof BNode expectedBNode) {
			BNode actualBNode = assertInstanceOf(BNode.class, actual, path + " remains a blank node");
			assertEquals(expectedBNode.getID(), actualBNode.getID(), path + " blank-node identifier");
			return;
		}
		if (expected instanceof Literal expectedLiteral) {
			Literal actualLiteral = assertInstanceOf(Literal.class, actual, path + " remains a literal");
			assertEquals(expectedLiteral.getLabel(), actualLiteral.getLabel(), path + " lexical label");
			assertEquals(expectedLiteral.getDatatype().stringValue(), actualLiteral.getDatatype().stringValue(),
					path + " datatype");
			assertEquals(expectedLiteral.getCoreDatatype(), actualLiteral.getCoreDatatype(), path + " core datatype");
			assertEquals(expectedLiteral.getLanguage(), actualLiteral.getLanguage(), path + " language");
			assertEquals(expectedLiteral.getBaseDirection(), actualLiteral.getBaseDirection(), path + " direction");
			return;
		}
		if (expected instanceof TripleTerm expectedTriple) {
			TripleTerm actualTriple = assertInstanceOf(TripleTerm.class, actual, path + " remains a triple term");
			assertEquivalentRdfValue(expectedTriple.getSubject(), actualTriple.getSubject(), path + ".subject");
			assertEquivalentRdfValue(expectedTriple.getPredicate(), actualTriple.getPredicate(), path + ".predicate");
			assertEquivalentRdfValue(expectedTriple.getObject(), actualTriple.getObject(), path + ".object");
			return;
		}
		throw new AssertionError("unsupported RDF value in test fixture: " + expected.getClass().getName());
	}

	private static void assertIriSplit(IRI expected, IRI actual) {
		assertEquals(expected.stringValue(), actual.stringValue(), "IRI lexical value");
		assertEquals(expected.getNamespace(), actual.getNamespace(), "IRI namespace");
		assertEquals(expected.getLocalName(), actual.getLocalName(), "IRI local name");
	}

	private static void seed(SailRepository repository) {
		try (var connection = repository.getConnection()) {
			connection.begin();
			connection.add(SIMPLE.createIRI("urn:builtin-cache:s1"), PREDICATE, SIMPLE.createLiteral("selected"));
			connection.add(SIMPLE.createIRI("urn:builtin-cache:s2"), PREDICATE, SIMPLE.createLiteral("selected"));
			connection.add(SIMPLE.createIRI("urn:builtin-cache:other"), PREDICATE, SIMPLE.createLiteral("other"));
			connection.commit();
		}
		try (var connection = repository.getConnection()) {
			connection.begin();
			((InferencerConnection) connection.getSailConnection()).addInferredStatement(
					SIMPLE.createIRI("urn:builtin-cache:s3"), PREDICATE, SIMPLE.createLiteral("selected"));
			connection.commit();
		}
	}

	private static void assertNumericConversionsPreserved(Literal original, String description) {
		LmdbQueryValueIdentity identity = new LmdbQueryValueIdentity.Capture().of(original);
		if (identity == null) {
			assertNotNull(identity, description + " source is an immutable built-in numeric literal");
			return;
		}
		Literal detached = (Literal) identity.value();
		assertAll(description,
				() -> assertEquals(original, detached, "detached literal equality"),
				() -> assertEquals(detached, original, "reverse detached literal equality"),
				() -> assertEquals(original.byteValue(), detached.byteValue(), "byteValue"),
				() -> assertEquals(original.shortValue(), detached.shortValue(), "shortValue"),
				() -> assertEquals(original.intValue(), detached.intValue(), "intValue"),
				() -> assertEquals(original.longValue(), detached.longValue(), "longValue"),
				() -> assertEquals(original.floatValue(), detached.floatValue(), "floatValue"),
				() -> assertEquals(original.doubleValue(), detached.doubleValue(), "doubleValue"),
				() -> assertEquals(original.integerValue(), detached.integerValue(), "integerValue"),
				() -> assertEquals(original.decimalValue(), detached.decimalValue(), "decimalValue"));
	}

	private static void assertIntegralConversionsPreserved(Literal original, String description) {
		assertNumericConversionsPreserved(original, description);
	}

	private static Map<String, Long> readBag(TupleQuery query) {
		Map<String, Long> bag = new TreeMap<>();
		try (var result = query.evaluate()) {
			while (result.hasNext()) {
				BindingSet row = result.next();
				String key = row.getValue("s").stringValue() + "\u0000" + row.getValue("o").stringValue();
				bag.merge(key, 1L, Long::sum);
			}
		}
		return bag;
	}

	private static String plannedMetric(TupleExpr plan, String name) {
		String value = plan.getStringMetricPlanned(name);
		if (value == null && plan instanceof org.eclipse.rdf4j.query.algebra.QueryRoot root && root.getArg() != null) {
			value = root.getArg().getStringMetricPlanned(name);
		}
		return value;
	}

