	private static final class ObservedNumber extends Number {
		private static final long serialVersionUID = 1L;
		private final AtomicInteger conversionCalls = new AtomicInteger();
		private volatile boolean observe;

		@Override
		public int intValue() {
			observed();
			return 7;
		}

		@Override
		public long longValue() {
			observed();
			return 7L;
		}

		@Override
		public float floatValue() {
			observed();
			return 7.0f;
		}

		@Override
		public double doubleValue() {
			observed();
			return 7.0d;
		}

		@Override
		public String toString() {
			observed();
			return "7";
		}

		private void observed() {
			if (observe) {
				conversionCalls.incrementAndGet();
			}
		}
	}

	private static final class ObservedCoreDatatype implements CoreDatatype {
		private final AtomicInteger getIriCalls = new AtomicInteger();
		private volatile boolean observe;

		@Override
		public IRI getIri() {
			if (observe) {
				getIriCalls.incrementAndGet();
			}
			return CoreDatatype.XSD.DOUBLE.getIri();
		}
	}

